INSERT INTO `ExampleSentence` VALUES (6939,3213,'明日の試験はとても難しいですから、頑張ってください。','Ashita no shiken wa totemo muzukashii desu kara, ganbatte kudasai.','Karena ujian besok sangat sulit, berjuanglah.',1),(6940,3213,'日本の大学の入学試験のために、毎日5時間勉強しています。','Nihon no daigaku no nyuugaku shiken no tame ni, mainichi gojikan benkyou shiteimasu.','Demi ujian masuk universitas Jepang, saya belajar 5 jam setiap hari.',1),(6941,3213,'卒業するために、来月面接試験を受けます。','Sotsugyou suru tame ni, raigetsu mensetsu shiken wo ukemasu.','Untuk lulus, saya akan mengikuti ujian wawancara bulan depan.',1),(6942,3213,'日本へ留学したことは、私にとって良い経験になりました。','Nihon he ryuugaku shita koto wa, watashi ni totte yoi keiken ni narimashita.','Belajar di Jepang telah menjadi pengalaman yang baik bagi saya.',1),(6943,3213,'化学の授業で, 水の性質を調べる実験を行いました。','Kagaku no jugyou de, mizu no seishitsu wo shiraberu jikken wo okonaimashita.','Dalam kelas kimia, kami melakukan eksperimen untuk memeriksa sifat-sifat air.',1),(6944,3214,'この問題は少し難しいです。','Kono mondai wa sukoshi muzukashii desu.','Soal ini sedikit sulit.',1),(6945,3214,'先生に質問してください。','Sensei ni shitsumon shitekudasai.','Silakan bertanya kepada guru.',1),(6946,3214,'日本では環境問題が重要です。','Nihon dewa kankyou mondai ga juuyou desu.','Di Jepang, masalah lingkungan adalah hal yang penting.',1),(6947,3214,'この問題集で勉強します。','Kono mondaishuu de benkyou shimasu.','Saya belajar menggunakan buku kumpulan soal ini.',1),(6948,3214,'電話で問い合わせをしました。','Denwa de toiawase wo shimashita.','Saya mengajukan pertanyaan via telepon.',1),(6949,3215,'宿題が多すぎて、昨日は寝る時間がありませんでした。','Shukudai ga oosugite, kinou wa neru jikan ga arimasen deshita.','Karena PR terlalu banyak, kemarin saya tidak punya waktu tidur.',1),(6950,3215,'今日のゼミでは、卒業論文の論題について議論します。','Kyou no zemi dewa, sotsugyou ronbun no rondai ni tsuite giron shimasu.','Di seminar hari ini, kami akan mendiskusikan tema tesis kelulusan.',1),(6951,3215,'面接試験では、最近の時事問題について質問されました。','Mensetsu shiken dewa, saikin no jiji mondai ni tsuite shitsumon saremashita.','Dalam ujian wawancara, saya ditanya tentang isu-isu aktual baru-baru ini.',1),(6952,3215,'彼女は自分の留学経験を題材にして小説を書きました。','Kanojo wa jibun no ryuugaku keiken wo daizai ni shite shousetsu wo kakimashita.','Dia menulis novel berdasarkan pengalaman belajarnya di luar negeri.',1),(6953,3215,'今週は課題がたくさんありますから、とても忙しいです。','Konshuu wa kadai ga takusan arimasu kara, totemo isogashii desu.','Karena minggu ini ada banyak tugas, saya sangat sibuk.',1),(6954,3216,'先生の質問に答えました。','Sensei no shitsumon ni kotaemashita.','Saya menjawab pertanyaan guru.',1),(6955,3216,'正しい答えを書いてください。','Tadashii kotae wo kaite kudasai.','Silakan tulis jawaban yang benar.',1),(6956,3216,'回答をメールで送りました。','Kaitou wo meeru de okurimashita.','Saya mengirimkan jawaban melalui email.',1),(6957,3216,'応答はなかなかありません。','Outou wa naka naka arimasen.','Responnya tidak kunjung datang.',1),(6958,3216,'一問一答はどういう意味ですか。','Ichimon ittou wa dou iu imi desu ka.','Apa arti dari \'satu pertanyaan satu jawaban\'?',1),(6959,3217,'先生はテストを採点しました。','Sensei wa tesuto wo saiten shimashita.','Guru menilai ujian tersebut.',1),(6960,3217,'私は百点を取りました。','Watashi wa hyakuten wo torimashita.','Saya mendapatkan nilai 100.',1),(6961,3217,'この作文の要点を書いてください。','Kono sakubun no youten wo kaite kudasai.','Silakan tulis poin penting dari esai ini.',1),(6962,3217,'先生は問題点を説明しました。','Sensei wa mondaiten wo setsumei shimashita.','Guru menjelaskan titik permasalahannya.',1),(6963,3217,'出発地点は駅です。','Shuppatsu chiten wa eki desu.','Titik keberangkatannya adalah stasiun.',1),(6976,3224,'情報の意味を調べます。','情報 no imi wo shirabemasu.','Memeriksa arti dari 情報 (Informasi).',1),(6977,3224,'感情について勉強します。','感情 ni tsuite benkyou shimasu.','Belajar tentang 感情 (Emosi).',1),(6978,3225,'情報の意味を調べます。','情報 no imi wo shirabemasu.','Memeriksa arti dari 情報 (Informasi).',1),(6979,3225,'報告について勉強します。','報告 ni tsuite benkyou shimasu.','Belajar tentang 報告 (Laporan).',1),(6980,3226,'伝言の意味を調べます。','伝言 no imi wo shirabemasu.','Memeriksa arti dari 伝言 (Pesan).',1),(6981,3226,'伝統について勉強します。','伝統 ni tsuite benkyou shimasu.','Belajar tentang 伝統 (Tradisi).',1),(6982,3227,'信用の意味を調べます。','信用 no imi wo shirabemasu.','Memeriksa arti dari 信用 (Kepercayaan).',1),(6983,3227,'信号について勉強します。','信号 ni tsuite benkyou shimasu.','Belajar tentang 信号 (Lampu Lalu Lintas).',1),(6984,3228,'受信の意味を調べます。','受信 no imi wo shirabemasu.','Memeriksa arti dari 受信 (Menerima Pesan).',1),(6985,3228,'受験について勉強します。','受験 ni tsuite benkyou shimasu.','Belajar tentang 受験 (Mengikuti Ujian).',1),(6986,3229,'送信の意味を調べます。','送信 no imi wo shirabemasu.','Memeriksa arti dari 送信 (Mengirim Pesan).',1),(6987,3229,'送金について勉強します。','送金 ni tsuite benkyou shimasu.','Belajar tentang 送金 (Transfer Uang).',1),(6988,3230,'職業の意味を調べます。','職業 no imi wo shirabemasu.','Memeriksa arti dari 職業 (Profesi).',1),(6989,3230,'職場について勉強します。','職場 ni tsuite benkyou shimasu.','Belajar tentang 職場 (Tempat Kerja).',1),(6990,3231,'職業の意味を調べます。','職業 no imi wo shirabemasu.','Memeriksa arti dari 職業 (Profesi).',1),(6991,3231,'産業について勉強します。','産業 ni tsuite benkyou shimasu.','Belajar tentang 産業 (Industri).',1),(6992,3232,'労働の意味を調べます。','労働 no imi wo shirabemasu.','Memeriksa arti dari 労働 (Tenaga Kerja).',1),(6993,3232,'共働きについて勉強します。','共働き ni tsuite benkyou shimasu.','Belajar tentang 共働き (Suami Istri Bekerja).',1),(6994,3233,'義務の意味を調べます。','義務 no imi wo shirabemasu.','Memeriksa arti dari 義務 (Kewajiban).',1),(6995,3233,'公務について勉強します。','公務 ni tsuite benkyou shimasu.','Belajar tentang 公務 (Tugas Publik).',1),(6996,3234,'技術の意味を調べます。','技術 no imi wo shirabemasu.','Memeriksa arti dari 技術 (Teknologi).',1),(6997,3234,'特技について勉強します。','特技 ni tsuite benkyou shimasu.','Belajar tentang 特技 (Keahlian Khusus).',1),(6998,3235,'技術の意味を調べます。','技術 no imi wo shirabemasu.','Memeriksa arti dari 技術 (Teknologi).',1),(6999,3235,'美術について勉強します。','美術 ni tsuite benkyou shimasu.','Belajar tentang 美術 (Seni Rupa).',1),(7000,3236,'会議の意味を調べます。','会議 no imi wo shirabemasu.','Memeriksa arti dari 会議 (Rapat).',1),(7001,3236,'議論について勉強します。','議論 ni tsuite benkyou shimasu.','Belajar tentang 議論 (Diskusi).',1),(7002,3237,'議論の意味を調べます