DROP TABLE IF EXISTS `Jukugo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `Jukugo` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kanjiId` int(11) NOT NULL,
  `word` varchar(191) NOT NULL,
  `reading` varchar(191) NOT NULL,
  `meaning` text NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Jukugo_kanjiId_fkey` (`kanjiId`),
  CONSTRAINT `Jukugo_kanjiId_fkey` FOREIGN KEY (`kanjiId`) REFERENCES `Kanji` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

