INSERT INTO `Module` VALUES (555,'Module 1','Mahasiswa mampu:\n- memahami makna dasar kanji 試・験・問・題・答・点\n- mengidentifikasi hubungan makna antar-kanji dalam jukugo akademik\n- menganalisis pembentukan jukugo yang berkaitan dengan evaluasi\n- memvisualisasikan hubungan makna melalui semantic graph\n- menggunakan jukugo akademik dalam kalimat sederhana'),(556,'Module 2','Mahasiswa mampu:\n- memahami makna dasar kanji penelitian dan ilmu pengetahuan\n- menjelaskan hubungan makna dalam jukugo bidang akademik\n- menganalisis pembentukan jukugo yang berkaitan dengan penelitian\n- menyusun semantic graph sederhana\n- menggunakan jukugo dalam konteks penelitian'),(557,'Module 3','Mahasiswa mampu:\n- memahami konsep pembelajaran dan pendidikan dalam bahasa Jepang\n- mengidentifikasi hubungan makna antar-kanji pendidikan\n- menganalisis pembentukan jukugo bidang pendidikan\n- menyusun semantic graph kanji pendidikan\n- menggunakan jukugo dalam konteks pembelajaran'),(558,'Module 4','Mahasiswa mampu:\n- memahami makna dasar kanji profesi dan pekerjaan\n- menjelaskan hubungan makna antar-kanji dalam dunia kerja\n- menganalisis jukugo yang berkaitan dengan profesi\n- menyusun semantic graph bidang pekerjaan\n- menggunakan jukugo dalam konteks profesi'),(559,'Module 5','Mahasiswa mampu:\n- memahami makna dasar kanji komunikasi\n- mengidentifikasi hubungan makna antar-kanji komunikasi\n- menganalisis pembentukan jukugo komunikasi\n- menyusun semantic graph komunikasi\n- menggunakan jukugo dalam percakapan dan diskusi'),(560,'Module 6','Mahasiswa mampu:\n- memahami konsep waktu dan pengalaman\n- menjelaskan hubungan makna antar-kanji terkait waktu\n- menganalisis pembentukan jukugo waktu dan pengalaman\n- menyusun semantic graph terkait pengalaman hidup\n- menggunakan jukugo dalam konteks kehidupan sehari-hari'),(561,'Module 7','Mahasiswa mampu:\n- memahami konsep perubahan dan perkembangan\n- menjelaskan hubungan makna antar-kanji perubahan\n- menganalisis pembentukan jukugo terkait perkembangan\n- menyusun semantic graph perubahan\n- menggunakan jukugo dalam konteks sosial dan akademik'),(562,'Module 8','Mahasiswa mampu:\n- memahami konsep berpikir dan penalaran\n- mengidentifikasi hubungan makna antar-kanji kognitif\n- menganalisis pembentukan jukugo yang berkaitan dengan pemikiran\n- menyusun semantic graph kognitif\n- menggunakan jukugo dalam konteks pengambilan keputusan'),(563,'Module 9','Mahasiswa mampu:\n- memahami konsep emosi dan sikap\n- menjelaskan hubungan makna antar-kanji emosi\n- menganalisis pembentukan jukugo yang berkaitan dengan perasaan\n- menyusun semantic graph emosi\n- menggunakan jukugo dalam konteks kehidupan sehari-hari'),(564,'Module 10','Mahasiswa mampu:\n- memahami konsep masyarakat dan organisasi\n- mengidentifikasi hubungan makna antar-kanji sosial\n- menganalisis pembentukan jukugo sosial\n- menyusun semantic graph sosial\n- menggunakan jukugo dalam konteks kemasyarakatan'),(565,'Module 11','Mahasiswa mampu:\n- memahami konsep logika dan argumentasi\n- menjelaskan hubungan makna antar-kanji logika\n- menganalisis pembentukan jukugo argumentatif\n- menyusun semantic graph logika\n- menggunakan jukugo dalam konteks akademik'),(566,'Module 12','Mahasiswa mampu:\n- memahami konsep ekonomi dan konsumsi\n- mengidentifikasi hubungan makna antar-kanji ekonomi\n- menganalisis pembentukan jukugo ekonomi\n- menyusun semantic graph ekonomi\n- menggunakan jukugo dalam konteks kehidupan modern');
/*!40000 ALTER TABLE `Module` ENABLE KEYS */;
UNLOCK TABLES;

