CREATE TABLE `Quiz` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kanjiId` int(11) NOT NULL,
  `question` text NOT NULL,
  `correctAnswer` text DEFAULT NULL,
  `explanation` text DEFAULT NULL,
  `correctOrder` text DEFAULT NULL,
  `groups` text DEFAULT NULL,
  `leftItems` text DEFAULT NULL,
  `options` text DEFAULT NULL,
  `pairs` text DEFAULT NULL,
  `rightItems` text DEFAULT NULL,
  `targetWord` text DEFAULT NULL,
  `type` varchar(191) NOT NULL DEFAULT 'multiple',
  `words` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Quiz_kanjiId_fkey` (`kanjiId`),
  CONSTRAINT `Quiz_kanjiId_fkey` FOREIGN KEY (`kanjiId`) REFERENCES `Kanji` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4949 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
