INSERT INTO `SemanticRelation` VALUES (12847,3220,'集 : berkumpul\n会 : bertemu\nHubungan makna antar kanji 集 dan 会 menjadi 集会, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"sekelompok orang yang berkumpul untuk mengadakan suatu pertemuan, rapat, atau kegiatan bersama.\"',14953),(12848,3220,'集 : mengumpulkan\n合 : menjadi satu\nHubungan makna antar kanji 集 dan 合 menjadi 集合, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"orang atau benda yang dikumpulkan menjadi satu tempat atau satu kelompok\".',14954),(12849,3220,'集 : berkumpul\n団 : kelompok\nHubungan makna antar kanji 集 dan 団 menjadi 集団, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"sekumpulan orang atau benda yang berhimpun sehingga membentuk suatu kelompok.\"',14955),(12850,3220,'集 : mengumpulkan\n客 : tamu / pelanggan\nHubungan makna antar kanji 集 dan 客 menjadi 集客, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan menarik atau menghimpun pelanggan agar datang ke suatu tempat atau menggunakan suatu layanan.\"',14956),(12851,3220,'収 : menghimpun / menerima\n集 : mengumpulkan\nHubungan makna antar kanji 収 dan 集 menjadi 収集, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menghimpun berbagai benda, data, atau informasi menjadi satu kumpulan.\"',14957),(12852,3220,'資料 : data, bahan, dokumen\n収集 : mengumpulkan\nHubungan makna antara 資料 dan 収集 menjadi 資料収集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"mengumpulkan berbagai data atau dokumen yang diperlukan sebagai bahan penelitian atau pembelajaran.\"',14957),(12853,3220,'情報 : informasi\n収集 : mengumpulkan\nHubungan makna antara 情報 dan 収集 menjadi 情報収集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"mengumpulkan berbagai informasi dari berbagai sumber sebagai bahan pertimbangan atau analisis.\"',14957),(12854,3220,'事実 : fakta\n収集 : mengumpulkan\nHubungan makna antara 事実 dan 収集 menjadi 事実収集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"mengumpulkan berbagai fakta yang diperlukan sebagai dasar penyelidikan atau analisis.\"',14957),(12855,3220,'集 : mengumpulkan\n中 : pusat\nHubungan makna antar kanji 集 dan 中 menjadi 集中, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"memusatkan perhatian atau pikiran pada satu hal sehingga tidak mudah teralihkan.\"',14961),(12856,3220,'集中 : konsentrasi\n力 : kekuatan\nHubungan makna antara 集中 dan 力 menjadi 集中力, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"kemampuan seseorang untuk memusatkan perhatian secara kuat terhadap suatu kegiatan.\"',14961),(12857,3220,'集中 : berkonsentrasi\n学習 : belajar\nHubungan makna antara 集中 dan 学習 menjadi 集中学習, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"kegiatan belajar yang dilakukan secara terpusat dan intensif dalam waktu tertentu.\"',14961),(12858,3220,'集中 : dipusatkan\n講義 : perkuliahan\nHubungan makna antara 集中 dan 講義 menjadi 集中講義, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"perkuliahan yang dilaksanakan secara intensif dan terpusat dalam jangka waktu tertentu.\"',14961),(12859,3220,'作品 : karya\n集 : kumpulan\nHubungan makna antara 作品 dan 集 menjadi 作品集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai karya yang dihimpun menjadi satu buku atau satu kumpulan.\"',14965),(12860,3220,'写真 : foto\n集 : kumpulan\nHubungan makna antara 写真 dan 集 menjadi 写真集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai foto yang dihimpun menjadi satu buku atau album.\"',14966),(12861,3220,'詩 : puisi\n集 : kumpulan\nHubungan makna antara 詩 dan 集 menjadi 詩集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai puisi yang dihimpun menjadi satu buku.\"',14967),(12862,3220,'問題 : soal\n集 : kumpulan\nHubungan makna antara 問題 dan 集 menjadi 問題集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai soal latihan yang dihimpun menjadi satu buku sebagai bahan belajar.\"',14968),(12863,3220,'記録 : catatan, rekaman\n集 : kumpulan\nHubungan makna antara 記録 dan 集 menjadi 記録集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai catatan atau rekaman yang dihimpun menjadi satu kumpulan atau dokumen.\"',14969),(12864,3220,'文書 : dokumen\n集 : kumpulan\nHubungan makna antara 文書 dan 集 menjadi 文書集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai dokumen yang dihimpun menjadi satu kumpulan untuk memudahkan penyimpanan atau penggunaan.\"',14970),(12865,3220,'報告 : laporan\n集 : kumpulan\nHubungan makna antara 報告 dan 集 menjadi 報告集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai laporan yang dihimpun menjadi satu dokumen atau buku laporan.\"',14971),(12866,3220,'事例 : contoh kasus\n集 : kumpulan\nHubungan makna antara 事例 dan 集 menjadi 事例集, menunjukkan bahwa gabungan kedua kata tersebut membentuk sebuah makna \"berbagai contoh kasus yang dihimpun menjadi satu buku atau dokumen sebagai bahan pembelajaran maupun referensi.\"',14972),(12872,3221,'体 ：tubuh\n調 ：kondisi, penyesuaian\nHubungan makna antar kanji 体 dan 調 menjadi 体調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan atau kondisi kesehatan tubuh seseorang.\"',14973),(12873,3221,'好 ：baik\n調 ：keadaan\nHubungan makna antar kanji 好 dan 調 menjadi 好調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang baik atau performa yang sedang meningkat.\"',14974),(12874,3221,'不 ：tidak\n調 ：keadaan\nHubungan makna antar kanji 不 dan 調 menjadi 不調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kondisi yang tidak baik atau mengalami gangguan.\"',14975),(12875,3221,'快 ：nyaman, menyenangkan\n調 ：keadaan\nHubungan makna antar kanji 快 dan 調 menjadi 快調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang sangat baik, sehat, atau suatu aktivitas yang berjalan dengan lancar.\"',14976),(12876,3221,'順 ：sesuai urutan\n調 ：keadaan\nHubungan makna antar kanji 順 dan 調 menjadi 順調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"suatu kegiatan atau proses yang berlangsung sesuai rencana tanpa mengalami hambatan.\"',14977),(12877,3221,'高 ：tinggi\n調 ：keadaan\nHubungan makna antar kanji 高 dan 調 menjadi 高調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang meningkat atau berada pada tingkat yang tinggi.\"',14978),(12878,3221,'低 ：rendah\n調 ：keadaan\nHubungan makna antar kanji 低 dan 調 menjadi 低調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang menurun, kurang aktif, atau tidak berkembang.\"',14979),(12879,3221,'口 ：mulut\n調 ：nada, cara\nHubungan makna antar kanji 口 dan 調 menjadi 口調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"cara seseorang berbicara atau menyampaikan sesuatu melalui nada dan gaya berbicara.\"',14980),(12880,3221,'語 ：bahasa\n調 ：nada\nHubungan makna antar kanji 語 dan 調 menjadi 語調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"gaya bahasa atau nada yang digunakan seseorang dalam berkomunikasi.\"',14981),(12881,3221,'声 ：suara\n調 ：nada\nHubungan makna antar kanji 声 dan 調 menjadi 声調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"tinggi rendah atau irama suara ketika mengucapkan suatu kata atau kalimat.\"',14982),(12882,3221,'音 ：bunyi\n調 ：irama\nHubungan makna antar kanji 音 dan 調 menjadi 音調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keselarasan tinggi rendah nada dalam bunyi atau musik.\"',14983),(12883,3221,'調 ：menyelidiki\n査 ：memeriksa\nHubungan makna antar kanji 調 dan 査 menjadi 調査, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan memeriksa atau menyelidiki suatu objek secara sistematis untuk memperoleh data atau informasi.\"',14984),(12884,3221,'調 ：menyelidiki\n書 ：dokumen\nHubungan makna antar kanji 調 dan 書 menjadi 調書, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"dokumen yang berisi hasil pemeriksaan, penyelidikan, atau pencatatan suatu peristiwa.\"',14985),(12885,3221,'調 ：menyepakati\n印 ：tanda tangan / cap\nHubungan makna antar kanji 調 dan 印 menjadi 調印, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan menandatangani suatu dokumen setelah isi perjanjian disepakati oleh para pihak.\"',14986),(12886,3221,'調 ：mengatur\n達 ：memperoleh\nHubungan makna antar kanji 調 dan 達 menjadi 調達, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan mengatur dan memperoleh barang atau perlengkapan yang diperlukan.\"',14987),(12887,3221,'調 ：mengolah\n理 ：mengatur\nHubungan makna antar kanji 調 dan 理 menjadi 調理, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"mengolah dan mengatur bahan makanan hingga siap dikonsumsi.\"',14988),(12888,3221,'調 ：menyesuaikan\n合 ：menggabungkan\nHubungan makna antar kanji 調 dan 合 menjadi 調合, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"mencampurkan beberapa bahan dengan komposisi yang sesuai sehingga menghasilkan campuran yang diinginkan.\"',14989),(12889,3221,'調 ：menyiapkan\n製 ：membuat\nHubungan makna antar kanji 調 dan 製 menjadi 調製, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menyiapkan atau membuat sesuatu sesuai kebutuhan atau tujuan tertentu.\"',14990),(12890,3221,'調 ：menyiapkan\n薬 ：obat\nHubungan makna antar kanji 調 dan 薬 menjadi 調薬, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menyiapkan atau meracik obat sesuai dengan resep atau kebutuhan pasien.\"',14991),(12891,3221,'調味 ：memberi rasa\n料 ：bahan\nHubungan makna antara 調味 dan 料 menjadi 調味料, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"bahan yang digunakan untuk menyesuaikan atau memperkaya cita rasa makanan.\"',14993),(12892,3221,'強 ：kuat\n調 ：menonjolkan\nHubungan makna antar kanji 強 dan 調 menjadi 強調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"memberikan penekanan yang kuat pada bagian yang dianggap penting.\"',14994),(12893,3221,'歩 ：berjalan\n調 ：irama\nHubungan makna antar kanji 歩 dan 調 menjadi 歩調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menyelaraskan langkah atau gerakan agar berjalan bersama secara teratur.\"',14995),(12894,3221,'変 ：berubah\n調 ：keadaan\nHubungan makna antar kanji 変 dan 調 menjadi 変調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"perubahan kondisi dari keadaan yang normal menjadi keadaan yang berbeda.\"',14996),(12895,3221,'移 ：memindahkan\n調 ：nada\nHubungan makna antar kanji 移 dan 調 menjadi 移調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"memindahkan tinggi rendah nada suatu lagu tanpa mengubah susunan melodinya.\"',14997),(12901,3222,'調 ：menyelidiki, meneliti\n査 ：memeriksa\nHubungan makna antar kanji 調 dan 査 menjadi 調査, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan memeriksa atau menyelidiki suatu objek secara sistematis untuk memperoleh data maupun informasi yang akurat.\"',14998),(12902,3222,'検 ：memeriksa\n査 ：mengecek secara teliti\nHubungan makna antar kanji 検 dan 査 menjadi 検査, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan memeriksa suatu objek, barang, atau kondisi tertentu untuk memastikan kualitas, keadaan, atau kesesuaiannya dengan standar.\"',14999),(12903,3222,'審 ：menilai dengan cermat\n査 ：memeriksa\nHubungan makna antar kanji 審 dan 査 menjadi 審査, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"proses memeriksa dan menilai sesuatu secara teliti sebelum memberikan keputusan atau penilaian.\"',15000),(12904,3222,'査 ：memeriksa\n定 ：menentukan\nHubungan makna antar kanji 査 dan 定 menjadi 査定, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menentukan nilai, harga, atau keputusan setelah melalui proses pemeriksaan secara teliti.\"',15001),(12905,3222,'査 ：memeriksa\n読 ：membaca\nHubungan makna antar kanji 査 dan 読 menjadi 査読, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"membaca dan memeriksa karya ilmiah secara cermat sebelum dipublikasikan.\"',15002),(12906,3222,'査 ：memeriksa\n問 ：bertanya\nHubungan makna antar kanji 査 dan 問 menjadi 査問, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"melakukan pemeriksaan melalui proses tanya jawab untuk menguji pengetahuan atau memperoleh kebenaran.\"',15003),(12907,3222,'再 ：kembali\n査 ：memeriksa\nHubungan makna antar kanji 再 dan 査 menjadi 再査, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"melakukan pemeriksaan kembali untuk memastikan atau memverifikasi hasil pemeriksaan sebelumnya.\"',15004),(12908,3222,'調査 ：penyelidikan\n研究 ：penelitian\nHubungan makna antara 調査 dan 研究 menjadi 調査研究, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"kegiatan penelitian yang dilakukan berdasarkan hasil penyelidikan dan pengumpulan data secara sistematis.\"',15005),(12909,3222,'調査 ：penelitian\n報告書 ：laporan\nHubungan makna antara 調査 dan 報告書 menjadi 調査報告書, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"dokumen resmi yang memuat hasil pemeriksaan, penyelidikan, atau penelitian.\"',15006),(12910,3222,'調査 ：penelitian\n資料 ：data atau dokumen\nHubungan makna antara 調査 dan 資料 menjadi 調査資料, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"kumpulan data, bahan, atau dokumen yang digunakan dalam proses penelitian atau penyelidikan.\"',15007),(12911,3222,'調査 ：penelitian\n記録 ：catatan\nHubungan makna antara 調査 dan 記録 menjadi 調査記録, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"catatan yang berisi seluruh proses maupun hasil kegiatan penelitian atau penyelidikan.\"',15008),(12912,3222,'調査 ：penelitian\n結果 ：hasil\nHubungan makna antara 調査 dan 結果 menjadi 調査結果, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"hasil akhir yang diperoleh setelah proses penelitian atau penyelidikan selesai dilakukan.\"',15009),(12913,3222,'学術 ：ilmu pengetahuan\n調査 ：penelitian\nHubungan makna antara 学術 dan 調査 menjadi 学術調査, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"kegiatan penelitian yang dilakukan untuk memperoleh atau mengembangkan pengetahuan ilmiah.\"',15010),(12914,3222,'現地 ：lokasi\n調査 ：penelitian\nHubungan makna antara 現地 dan 調査 menjadi 現地調査, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"kegiatan penelitian atau pengumpulan data yang dilakukan secara langsung di lokasi penelitian.\"',15011),(12915,3222,'市場 ：pasar\n調査 ：penelitian\nHubungan makna antara 市場 dan 調査 menjadi 市場調査, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"kegiatan menyelidiki kondisi, kebutuhan, atau perilaku pasar sebagai dasar pengambilan keputusan.\"',15012),(12916,3222,'統計 ：statistik\n調査 ：penelitian\nHubungan makna antara 統計 dan 調査 menjadi 統計調査, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"kegiatan pengumpulan data secara sistematis untuk dianalisis menggunakan metode statistik.\"',15013),(12917,3222,'調査 ：penelitian\n対象 ：sasaran\nHubungan makna antara 調査 dan 対象 menjadi 調査対象, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"objek atau sasaran yang menjadi fokus dalam kegiatan penelitian atau penyelidikan.\"',15014),(12918,3222,'調査 ：penelitian\n方法 ：metode\nHubungan makna antara 調査 dan 方法 menjadi 調査方法, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"cara atau prosedur yang digunakan untuk melakukan kegiatan penelitian atau penyelidikan.\"',15015),(12919,3222,'調査 ：penelitian\n内容 ：isi\nHubungan makna antara 調査 dan 内容 menjadi 調査内容, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"hal-hal yang menjadi materi atau ruang lingkup dalam kegiatan penelitian.\"',15016),(12920,3222,'調査 ：penelitian\n目的 ：tujuan\nHubungan makna antara 調査 dan 目的 menjadi 調査目的, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"tujuan yang ingin dicapai melalui kegiatan penelitian atau penyelidikan.\"',15017),(12926,3223,'事 ：peristiwa, kejadian\n実 ：kenyataan\nHubungan makna antar kanji 事 dan 実 menjadi 事実, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"suatu peristiwa atau kejadian yang benar-benar terjadi sehingga menjadi fakta.\"',15018),(12927,3223,'真 ：benar, asli\n実 ：kenyataan\nHubungan makna antar kanji 真 dan 実 menjadi 真実, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kebenaran yang sesuai dengan kenyataan yang sebenarnya.\"',15019),(12928,3223,'実 ：nyata\n話 ：cerita\nHubungan makna antar kanji 実 dan 話 menjadi 実話, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"cerita yang berasal dari kejadian yang benar-benar terjadi.\"',15020),(12929,3223,'実 ：nyata\n感 ：perasaan\nHubungan makna antar kanji 実 dan 感 menjadi 実感, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"perasaan atau kesadaran yang benar-benar dirasakan secara langsung.\"',15021),(12930,3223,'口 ：mulut, ucapan\n実 ：kenyataan\nHubungan makna antar kanji 口 dan 実 menjadi 口実, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"alasan atau ucapan yang digunakan sebagai dalih untuk melakukan atau menjelaskan sesuatu.\"',15022),(12931,3223,'実 ：nyata, praktik\n験 ：menguji\nHubungan makna antar kanji 実 dan 験 menjadi 実験, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan melakukan pengujian secara nyata untuk memperoleh hasil atau membuktikan sesuatu.\"',15023),(12932,3223,'実 ：praktik\n習 ：belajar\nHubungan makna antar kanji 実 dan 習 menjadi 実習, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan belajar yang dilakukan melalui praktik secara langsung.\"',15024),(129